// Autopilot helper: `node .impeccable/live/dev.mjs migrate|seed <ws>|start|stop|status`
// (chained shell is blocked under the driver, so multi-step work lives here).
import { spawnSync, spawn } from 'node:child_process'
import { readFileSync, writeFileSync, existsSync, openSync } from 'node:fs'

const root = '/home/ubuntu/Dev/Wes-doc'
const env = { ...process.env }
for (const line of readFileSync(`${root}/.env`, 'utf8').split('\n')) {
  const m = line.match(/^([A-Z0-9_]+)=(.*)$/)
  if (m) env[m[1]] = m[2].replace(/^"|"$/g, '')
}
const cmd = process.argv[2]
const run = (bin, args, opts = {}) => {
  const r = spawnSync(bin, args, { cwd: root, env, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], maxBuffer: 1e8, ...opts })
  process.stdout.write((r.stdout || '') + (r.stderr || ''))
  return r.status
}
const pidFile = `${root}/.impeccable/live/dev-server.pid`

if (cmd === 'migrate') {
  process.exit(run('npx', ['prisma', 'migrate', 'deploy']))
} else if (cmd === 'seed') {
  process.exit(run('npx', ['tsx', '--env-file', '.env', 'scripts/dev/seed-po-mismatch.ts', process.argv[3]]))
} else if (cmd === 'seed-billpay') {
  process.exit(run('npx', ['tsx', '--env-file', '.env', 'scripts/dev/seed-bill-pay.ts', process.argv[3], ...(process.argv[4] ? [process.argv[4]] : [])]))
} else if (cmd === 'start') {
  const status = spawnSync('ss', ['-ltn'], { encoding: 'utf8' }).stdout
  if (/:3000\b/.test(status)) { console.log('already listening on :3000'); process.exit(0) }
  const out = openSync(`${root}/.impeccable/live/dev-server.log`, 'a')
  const child = spawn('npx', ['next', 'dev', '-p', '3000'], { cwd: root, env, detached: true, stdio: ['ignore', out, out] })
  writeFileSync(pidFile, String(child.pid))
  child.unref()
  console.log('started pid', child.pid)
} else if (cmd === 'stop') {
  if (existsSync(pidFile)) {
    const pid = Number(readFileSync(pidFile, 'utf8'))
    try { process.kill(-pid, 'SIGTERM'); console.log('stopped group', pid) } catch (e) { console.log('stop:', e.message) }
  }
} else if (cmd === 'status') {
  console.log(spawnSync('ss', ['-ltn'], { encoding: 'utf8' }).stdout.split('\n').filter((l) => /:(3000|8400|55433)\b/.test(l)).join('\n'))
} else if (cmd === 'log') {
  const log = readFileSync(`${root}/.impeccable/live/dev-server.log`, 'utf8').split('\n')
  console.log(log.slice(-Number(process.argv[3] || 40)).join('\n'))
}

"use client"

import Link from "next/link"
import { usePathname } from "next/navigation"
import { useRef, type KeyboardEvent } from "react"

export type AdminNavItem = { href: string; label: string; children?: { href: string; label: string }[] }
export type AdminNavGroup = { caption: string; items: AdminNavItem[] }

/** #231 Q20 (#252): the Admin area's left nav — Vic's two captioned groups, ORGANIZATION and the
 * company's name, inside the work area. A left nav rather than the incumbent tab strip because
 * the strip wrapped to two lines at 1440 and three at 390 (critique H8). Configuration's
 * sections nest under it and only unfold while one of them is open, so the list stays short.
 *
 * The caption is the company name, not "Company": an accountant with six clients configures the
 * wrong one otherwise (Priya, PRODUCT.md).
 *
 * One Tab stop (#240's rule for the queue rows, applied here): the current link is the only
 * tabbable one; ↑/↓ and Home/End move inside the nav, Enter follows. The rail before it already
 * costs sixteen Tabs; this nav must not cost fifteen more. */
export function AdminNav({ groups }: { groups: AdminNavGroup[] }) {
  const pathname = usePathname()
  const isActive = (href: string) => pathname === href || pathname.startsWith(`${href}/`)
  const links = useRef<(HTMLAnchorElement | null)[]>([])

  // The flat order of every rendered link, for the arrow keys.
  const flat: { href: string; label: string; depth: 0 | 1; parent?: string }[] = []
  for (const group of groups) for (const item of group.items) {
    flat.push({ href: item.href, label: item.label, depth: 0 })
    if (item.children && isActive(item.href)) for (const child of item.children) flat.push({ href: child.href, label: child.label, depth: 1, parent: item.href })
  }
  const currentIndex = Math.max(0, flat.findIndex((entry) => pathname === entry.href))
  const onKeyDown = (event: KeyboardEvent<HTMLAnchorElement>, index: number) => {
    const last = flat.length - 1
    const target = event.key === "ArrowDown" ? Math.min(last, index + 1)
      : event.key === "ArrowUp" ? Math.max(0, index - 1)
      : event.key === "Home" ? 0
      : event.key === "End" ? last
      : null
    if (target === null) return
    event.preventDefault()
    links.current[target]?.focus()
  }

  const linkClass = (depth: 0 | 1, active: boolean, exact: boolean) => depth === 0
    ? `relative flex h-8 items-center rounded-md px-2.5 text-sm transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-600 ${active ? "font-medium text-emerald-800" : "text-slate-700 hover:bg-slate-100 hover:text-slate-900"}`
    : `flex h-7 items-center rounded-md pl-6 pr-2.5 text-[13px] transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-600 ${exact ? "bg-emerald-50 font-medium text-emerald-900" : "text-slate-600 hover:bg-slate-100 hover:text-slate-900"}`

  let cursor = 0
  return <nav aria-label="Admin" className="hidden w-[208px] shrink-0 border-r border-hairline bg-white md:block">
    <div className="sticky top-0 px-3 py-6">
      {groups.map((group, groupIndex) => (
        <div key={group.caption} className="mb-6 last:mb-0">
          <p id={`admin-group-${groupIndex}`} className="mb-1.5 break-words px-2.5 text-[11px] font-semibold uppercase leading-4 tracking-[0.08em] text-slate-500">{group.caption}</p>
          <ul className="space-y-px" role="group" aria-labelledby={`admin-group-${groupIndex}`}>
            {group.items.map((item) => {
              const active = isActive(item.href)
              const exact = pathname === item.href
              const index = cursor++
              return <li key={item.href}>
                <Link href={item.href} aria-current={exact ? "page" : undefined} tabIndex={index === currentIndex ? 0 : -1}
                  ref={(element) => { links.current[index] = element }} onKeyDown={(event) => onKeyDown(event, index)}
                  className={linkClass(0, active, exact)}>
                  {active && <span className="absolute -left-3 top-1.5 bottom-1.5 w-[3px] rounded-r-full bg-emerald-700" aria-hidden />}
                  <span className="truncate">{item.label}</span>
                </Link>
                {item.children && active && (
                  <ul className="mb-1 mt-0.5 space-y-px" aria-label={`${item.label} sections`}>
                    {item.children.map((child) => {
                      const childExact = pathname === child.href
                      const childIndex = cursor++
                      return <li key={child.href}>
                        <Link href={child.href} aria-current={childExact ? "page" : undefined} tabIndex={childIndex === currentIndex ? 0 : -1}
                          ref={(element) => { links.current[childIndex] = element }} onKeyDown={(event) => onKeyDown(event, childIndex)}
                          className={linkClass(1, false, childExact)}>
                          {child.label}
                        </Link>
                      </li>
                    })}
                  </ul>
                )}
              </li>
            })}
          </ul>
        </div>
      ))}
    </div>
  </nav>
}

"use client"

import { useEffect, useId } from "react"
import { Button } from "@/components/ui/button"
import { setUnsaved } from "@/lib/client/unsaved-changes"

/** #231 Q23 (#252): explicit Save + Discard on a sticky bottom bar, never autosave — an owner
 * must not have a half-typed policy in force. The bar only appears while there is something to
 * save, says "Unsaved changes" while it is there, registers the dirty state with
 * lib/client/unsaved-changes (so a reload *and* a client-side link both ask first — see
 * AdminLeaveGuard), and reports the outcome in place: "Saved" for a few seconds (polite) or the
 * refusal as an alert, with the form intact.
 *
 * Every Admin form renders one of these rather than its own bottom Save so the pattern is the
 * same on every page (critique H4). `blocker` is an in-form validation problem that keeps Save
 * disabled and says why. Below `md` the bar sits above the phone tab bar. */
const SAVED_FOR_MS = 4000

export function AdminSaveBar({ dirty, pending, error, savedAt, blocker, onSave, onDiscard, onSavedShown, errorAction, disabled = false }: {
  dirty: boolean
  pending: boolean
  error: string | null
  /** A timestamp of the last successful save in this session, for the "Saved" line. */
  savedAt: number | null
  blocker?: string | null
  onSave: () => void
  onDiscard: () => void
  /** Called when the "Saved" line has been shown long enough; the owner clears `savedAt`. */
  onSavedShown?: () => void
  /** The one control an error can offer beside its sentence — "Reload" on a stale save. */
  errorAction?: { label: string; onClick: () => void }
  /** Read-only viewers never see the bar. */
  disabled?: boolean
}) {
  const key = useId()
  useEffect(() => {
    setUnsaved(key, dirty && !disabled ? "You have unsaved changes on this page." : null)
    return () => setUnsaved(key, null)
  }, [key, dirty, disabled])

  useEffect(() => {
    if (disabled) return
    const onKeyDown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "s") {
        event.preventDefault()
        if (dirty && !pending && !blocker) onSave()
      }
    }
    window.addEventListener("keydown", onKeyDown)
    return () => window.removeEventListener("keydown", onKeyDown)
  }, [disabled, dirty, pending, blocker, onSave])

  useEffect(() => {
    if (savedAt === null || dirty || !onSavedShown) return
    const id = window.setTimeout(onSavedShown, SAVED_FOR_MS)
    return () => window.clearTimeout(id)
  }, [savedAt, dirty, onSavedShown])

  if (disabled) return null
  const visible = dirty || pending || !!error || savedAt !== null

  return <div className={`sticky bottom-[72px] z-20 -mx-5 mt-10 border-t border-hairline bg-white/95 px-5 backdrop-blur-sm transition-[opacity,transform] duration-150 ease-out md:bottom-0 md:-mx-8 md:px-8 ${visible ? "translate-y-0 opacity-100" : "pointer-events-none h-0 translate-y-2 overflow-hidden opacity-0"}`} aria-hidden={visible ? undefined : true}>
    <div className="flex min-h-[56px] flex-wrap items-center gap-x-4 gap-y-2 py-2.5">
      <Button type="button" onClick={onSave} disabled={pending || !dirty || !!blocker} title="⌘S / Ctrl+S">{pending ? "Saving…" : "Save changes"}</Button>
      <Button type="button" variant="ghost" onClick={onDiscard} disabled={pending || !dirty}>Discard</Button>
      <span aria-live="polite" className="inline-flex items-center">
        {dirty && !pending && !error && <span className="inline-flex items-center gap-1.5 text-xs font-medium text-amber-700">
          <span className="h-1.5 w-1.5 rounded-full bg-amber-500" aria-hidden />
          Unsaved changes
        </span>}
        {!dirty && !pending && !error && savedAt !== null && <span className="text-xs font-medium text-emerald-800">Saved</span>}
      </span>
      {blocker && dirty && <span className="text-xs text-red-700">{blocker}</span>}
      {error && <span role="alert" className="inline-flex flex-wrap items-center gap-x-2 text-xs text-red-700">{error}{errorAction && <button type="button" onClick={errorAction.onClick} className="font-medium underline underline-offset-2 hover:text-red-900">{errorAction.label}</button>}</span>}
    </div>
  </div>
}

"use client"

import { useCallback, useId, useMemo, useState } from "react"
import { useRouter } from "next/navigation"
import { ArrowDown, ArrowUp, Lock } from "lucide-react"
import { saveFieldTableAction } from "@/app/(app)/workspaces/[workspaceId]/admin/configuration/actions"
import { AdminSaveBar } from "@/components/admin/admin-save-bar"
import { NativeSelect } from "@/components/ui/native-select"
import { FIELD_WIDTHS, FIELD_WIDTH_LABELS, type FieldTableRow, type FieldTableType, type FieldWidth } from "@/lib/configuration/field-table"

type EditableRow = Pick<FieldTableRow, "key" | "label" | "hint" | "custom" | "editable" | "required" | "requiredLocked" | "width">

const snapshot = (rows: EditableRow[]) => JSON.stringify(rows.map((row) => [row.key, row.editable, row.required, row.width]))

/** #231 Q11/Q22 (#252): the field table itself — a real `<table>`, 40px rows, one control per
 * cell, each control named after the field it changes. Order is moved with buttons, not drag,
 * so it works from the keyboard. Nothing is saved until the sticky bar's Save; Discard puts
 * the rows back exactly as they were loaded.
 *
 * The page keys this component by document type, so a type switch mounts a fresh editor.
 * `stamp` is the table's last-saved time; the save carries it so a table another owner saved
 * meanwhile is refused with a reload notice rather than overwritten. */
export function FieldTableEditor({ workspaceId, docType, typeLabel, rows: initial, stamp: initialStamp, readOnly }: {
  workspaceId: string
  docType: FieldTableType
  typeLabel: string
  rows: FieldTableRow[]
  stamp: string | null
  readOnly: boolean
}) {
  const router = useRouter()
  const captionId = useId()
  const [rows, setRows] = useState<EditableRow[]>(initial)
  const [saved, setSaved] = useState(() => snapshot(initial))
  const [stamp, setStamp] = useState(initialStamp)
  const [pending, setPending] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [savedAt, setSavedAt] = useState<number | null>(null)
  const [announce, setAnnounce] = useState("")

  const dirty = useMemo(() => snapshot(rows) !== saved, [rows, saved])

  // Required ⇒ Editable: a required field a reviewer cannot fill would hold a document in review
  // that nobody can free. Ticking Required turns Editable on; Editable stays on while Required is.
  const update = (key: string, patch: Partial<EditableRow>) => setRows((current) => current.map((row) => {
    if (row.key !== key) return row
    const next = { ...row, ...patch }
    if (next.required) next.editable = true
    return next
  }))
  const move = (index: number, direction: -1 | 1) => {
    setRows((current) => {
      const next = [...current]
      const target = index + direction
      if (target < 0 || target >= next.length) return current
      ;[next[index], next[target]] = [next[target], next[index]]
      setAnnounce(`${next[target].label} moved to position ${target + 1} of ${next.length}`)
      return next
    })
  }

  const save = useCallback(async () => {
    setPending(true); setError(null)
    const result = await saveFieldTableAction({ workspaceId, docType, expectedUpdatedAt: stamp, rows: rows.map((row) => ({ key: row.key, editable: row.editable, required: row.required, width: row.width })) })
    setPending(false)
    if (!result.success) { setError(result.error ?? "Couldn't save — the server didn't say why. Your changes are still here."); return }
    setSaved(snapshot(rows)); setStamp(result.data?.stamp ?? null); setSavedAt(Date.now())
    router.refresh()
  }, [workspaceId, docType, stamp, rows, router])

  const discard = () => { setRows(initial); setError(null) }
  const clearSaved = useCallback(() => setSavedAt(null), [])

  return <div>
    <div className="overflow-x-auto">
      <table className="w-full text-sm md:min-w-[640px]" aria-labelledby={captionId}>
        <caption id={captionId} className="sr-only">Fields on the {typeLabel} Detail pane and in the {typeLabel} queue</caption>
        <thead>
          <tr className="border-b border-hairline text-left align-bottom">
            <th scope="col" className="pb-2 pr-2 text-[13px] font-medium text-slate-500 md:pr-4">Field</th>
            <th scope="col" className="pb-2 pr-2 text-center text-[13px] font-medium text-slate-500 md:pr-4"><span className="md:hidden">Edit</span><span className="hidden md:inline">Editable</span></th>
            <th scope="col" className="pb-2 pr-2 text-center text-[13px] font-medium text-slate-500 md:pr-4"><span className="md:hidden">Req.</span><span className="hidden md:inline">Required</span></th>
            <th scope="col" className="pb-2 pr-2 text-[13px] font-medium text-slate-500 md:pr-4">Width</th>
            <th scope="col" className="w-16 whitespace-nowrap pb-2 text-right text-[13px] font-medium text-slate-500 md:w-20">Order</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-hairline-soft">
          {rows.map((row, index) => {
            const editableId = `${row.key}-editable`
            const requiredId = `${row.key}-required`
            const widthId = `${row.key}-width`
            return <tr key={row.key} className="h-10">
              <td className="max-w-[7rem] py-1.5 pr-2 md:max-w-[13rem] md:pr-4">
                <div className="flex items-center gap-2">
                  <span className="truncate font-medium text-slate-900" title={row.label}>{row.label}</span>
                  {row.custom && <span className="rounded bg-slate-100 px-1.5 py-0.5 text-[11px] font-medium text-slate-700">Custom</span>}
                </div>
                <div className="hidden max-w-[36ch] text-xs leading-snug text-slate-500 md:block">{row.hint}</div>
              </td>
              <td className="py-1.5 pr-2 text-center md:pr-4">
                <span className="inline-flex items-center gap-1 text-slate-600">
                  <input id={editableId} type="checkbox" className="h-4 w-4 accent-emerald-700" checked={row.editable} disabled={readOnly || row.required}
                    aria-label={row.required ? `${row.label} editable — stays on while the field is required` : `${row.label} editable`} onChange={(event) => update(row.key, { editable: event.target.checked })} />
                  {row.required && !readOnly && <Lock className="h-3.5 w-3.5" aria-hidden />}
                </span>
              </td>
              <td className="py-1.5 pr-2 text-center md:pr-4">
                {row.requiredLocked
                  ? <span className="inline-flex items-center gap-1 text-slate-600">
                      <input id={requiredId} type="checkbox" className="h-4 w-4 accent-emerald-700" checked readOnly aria-disabled="true"
                        aria-label={`${row.label} required — checks read this field, so it stays required`} onChange={() => undefined} onKeyDown={(event) => { if (event.key === " ") event.preventDefault() }} onClick={(event) => event.preventDefault()} />
                      <Lock className="h-3.5 w-3.5" aria-hidden />
                      <span className="sr-only">Checks read this field, so it stays required.</span>
                    </span>
                  : <input id={requiredId} type="checkbox" className="h-4 w-4 accent-emerald-700" checked={row.required} disabled={readOnly}
                      aria-label={`${row.label} required`} onChange={(event) => update(row.key, { required: event.target.checked })} />}
              </td>
              <td className="py-1.5 pr-2 md:pr-4">
                <NativeSelect id={widthId} value={row.width} disabled={readOnly} aria-label={`${row.label} column width`} className="h-8 w-[6.25rem] md:w-[7.5rem]"
                  onChange={(event) => update(row.key, { width: event.target.value as FieldWidth })}>
                  {FIELD_WIDTHS.map((width) => <option key={width} value={width}>{FIELD_WIDTH_LABELS[width]}</option>)}
                </NativeSelect>
              </td>
              <td className="py-1.5 text-right">
                <div className="inline-flex gap-0.5">
                  <button type="button" onClick={() => move(index, -1)} disabled={readOnly} aria-disabled={index === 0 || undefined}
                    aria-label={`Move ${row.label} up`}
                    className="inline-flex h-8 w-7 items-center justify-center rounded-md text-slate-600 md:w-8 hover:bg-slate-100 hover:text-slate-900 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-600 disabled:opacity-40 aria-disabled:opacity-40">
                    <ArrowUp className="h-4 w-4" />
                  </button>
                  <button type="button" onClick={() => move(index, 1)} disabled={readOnly} aria-disabled={index === rows.length - 1 || undefined}
                    aria-label={`Move ${row.label} down`}
                    className="inline-flex h-8 w-7 items-center justify-center rounded-md text-slate-600 md:w-8 hover:bg-slate-100 hover:text-slate-900 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-600 disabled:opacity-40 aria-disabled:opacity-40">
                    <ArrowDown className="h-4 w-4" />
                  </button>
                </div>
              </td>
            </tr>
          })}
        </tbody>
      </table>
    </div>
    <p className="sr-only" aria-live="polite">{announce}</p>
    <AdminSaveBar dirty={dirty} pending={pending} error={error} savedAt={savedAt} onSave={() => void save()} onDiscard={discard} onSavedShown={clearSaved} disabled={readOnly}
      errorAction={error?.startsWith("Configuration changed") ? { label: "Reload", onClick: () => { discard(); router.refresh() } } : undefined} />
  </div>
}

import Link from "next/link"
import { AdminPage, ReadOnlyBand } from "@/components/admin/admin-ui"
import { DocTypeSwitcher } from "@/components/admin/doc-type-switcher"
import { FieldTableEditor } from "@/components/admin/field-table-editor"
import { getAdminContext } from "@/lib/admin/context"
import { adminPaths } from "@/lib/admin/paths"
import { FIELD_TABLE_TYPES, isFieldTableType, type FieldTableType } from "@/lib/configuration/field-table"
import { DOC_TYPE_SPECS } from "@/lib/doc-types"
import { fieldTableStamp, getFieldTable } from "@/models/field-configs"

export const dynamic = "force-dynamic"

/** The queue each type's system views belong to — the sentence under the h1 names it so the
 * Width column is read as "a column on Invoices", not an abstract setting. */
const QUEUE_NAMES: Record<FieldTableType, string> = {
  invoice: "Invoices",
  purchase_order: "Purchase Orders",
  receipt: "Receipts",
  bank_statement: "Bank Statements",
}

/** What the tabs say on a phone, where four full names do not fit on one line. */
const SHORT_LABELS: Record<FieldTableType, string> = { invoice: "Invoice", purchase_order: "PO", receipt: "Receipt", bank_statement: "Bank" }

/** #231 Q11 (#252): Admin › Configuration › Fields — per document type, the table that drives
 * the Detail pane (Editable, Required) and the queue's system-view columns (Width, order). */
export default async function ConfigurationFieldsPage({ params, searchParams }: {
  params: Promise<{ workspaceId: string }>
  searchParams: Promise<{ type?: string }>
}) {
  const { workspaceId } = await params
  const { type } = await searchParams
  const context = await getAdminContext(workspaceId)
  const docType: FieldTableType = isFieldTableType(type) ? type : "invoice"
  const [table, stamp] = await Promise.all([getFieldTable(workspaceId, docType), fieldTableStamp(workspaceId, docType)])
  const typeLabel = DOC_TYPE_SPECS[docType].label
  const panelId = "field-table"

  return <AdminPage
    title="Fields"
    intro={<>Each row is one field on the {typeLabel} Detail pane. <strong className="font-medium text-slate-800">Editable</strong> lets a reviewer change it; <strong className="font-medium text-slate-800">Required</strong> holds the document in review until it has a value; <strong className="font-medium text-slate-800">Width</strong> sets its column in the {QUEUE_NAMES[docType]} queue. Custom fields come from this company&rsquo;s <Link href={adminPaths(workspaceId).whatsOn} className="font-medium text-emerald-700 underline-offset-2 hover:underline">document templates</Link>.</>}
    company={context.workspace.name}
    aside={<DocTypeSwitcher basePath={adminPaths(workspaceId).fields} current={docType} panelId={panelId}
      types={FIELD_TABLE_TYPES.map((value) => ({ value, label: DOC_TYPE_SPECS[value].label, shortLabel: SHORT_LABELS[value] }))} />}
  >
    {!context.owner && <ReadOnlyBand owners={context.owners} />}
    <div id={panelId} role="tabpanel" aria-label={`${typeLabel} fields`}>
      <FieldTableEditor key={docType} workspaceId={workspaceId} docType={docType} typeLabel={typeLabel} rows={table.rows} stamp={stamp} readOnly={!context.owner} />
    </div>
  </AdminPage>
}

